  {"label": "volatile", "gloss": "This means having moods that shift suddenly and sharply, so that others cannot predict how the person will react from one moment to the next.", "antonym": "even-tempered", "kind": "trait", "ambiguity_flag": true, "probability": 0.4},
  {"label": "volcanic temper", "gloss": "This means being prone to sudden, explosive anger that erupts quickly over small provocations and then passes.", "antonym": "mild-tempered", "kind": "trait", "ambiguity_flag": false, "probability": 0.15},
  {"label": "vocal", "gloss": "This means openly and frequently stating one's opinions and feelings, rather than keeping them private or letting others speak for you.", "antonym": "reserved", "kind": "trait", "ambiguity_flag": true, "probability": 0.45},
  {"label": "vexatious", "gloss": "This means habitually pursuing complaints, disputes or demands that annoy and wear down others, even when they have little real merit.", "antonym": "conciliatory", "kind": "trait", "ambiguity_flag": false, "probability": 0.1}
 ]}

