  {"label": "circumspect", "gloss": "This means being cautious and careful, weighing possible consequences before acting or speaking, and avoiding rash commitments.", "antonym": "heedless", "kind": "trait", "ambiguity_flag": false, "probability": 0.6},
  {"label": "civil", "gloss": "This means being politely respectful and courteous in dealings with others, even when disagreeing or under strain.", "antonym": "uncivil", "kind": "trait", "ambiguity_flag": true, "probability": 0.5},
